    "stalledContext": "這一期補薪付了，助理還是換到別的團隊。{task}沒談完，新的署名頁上有一格還空著，旁邊夾著助理退回的便條。傾城把邀請信看了好幾次，沒有再寄。她拿出那張署名頁給你看，架上的獎狀，今天她一次也沒有提起。",
