        "context": "唱片裡有一個錯音，紀嚴特地倒回去讓你聽，說那是很好的處理。輪到他自己彈，同一個地方失手，他卻馬上從頭來過。你指出這個差別，他的手停在琴鍵上。錄音還開著，可以從頭再來，也可以先聽完。他抬頭問你想選哪一種，這次沒有自己先把前面刪掉。",
        "line": "「別人那個叫處理。我這個叫錯。……你想聽完整的，還是到這裡就好？」",
